#!/usr/bin/env node
/**
 * Fail-closed evidence gate for an OFFLINE OSV-Scanner JSON report.
 * This checker never downloads an advisory database or calls a provider.
 * The report and signed-off metadata must be generated by a separate actual
 * offline scanner run against the exact lockfile. A report alone is not proof.
 *
 * Usage:
 *   node scripts/verify-offline-osv-report.mjs report.json evidence.json
 *
 * Evidence fields: scanMode ("offline"), lockfileSha256 (64 hex characters),
 * advisorySnapshotSha256 (64 hex characters), advisorySnapshotDate (ISO date),
 * scannerVersion, gitCommit (40 hex characters), lockfile ("package-lock.json").
 * Operator must independently verify these values against actual artifacts.
 */
import { readFileSync } from "node:fs";

function fail(message) {
  process.stderr.write(`OSV OFFLINE GATE FAILED: ${message}\n`);
  process.exit(1);
}
if (process.argv.length !== 4) fail("report and evidence paths are required");
let report, evidence;
try {
  report = JSON.parse(readFileSync(process.argv[2], "utf8"));
  evidence = JSON.parse(readFileSync(process.argv[3], "utf8"));
} catch {
  fail("missing or invalid offline report/evidence JSON");
}
if (evidence.scanMode !== "offline") fail("scan was not attested as offline");
for (const field of ["lockfileSha256", "advisorySnapshotSha256"]) {
  if (!/^[0-9a-f]{64}$/i.test(evidence[field] || "")) fail(`missing valid ${field}`);
}
if (!/^\d{4}-\d{2}-\d{2}$/.test(evidence.advisorySnapshotDate || "")) fail("advisory snapshot date missing");
if (!/^[0-9a-f]{40}$/i.test(evidence.gitCommit || "")) fail("exact commit SHA missing");
if (evidence.lockfile !== "package-lock.json") fail("wrong lockfile");
if (typeof evidence.scannerVersion !== "string" || !evidence.scannerVersion.trim()) fail("scanner version missing");
if (!Array.isArray(report.results)) fail("OSV-Scanner results array missing");
const findings = report.results.flatMap(result =>
  (result.packages || []).flatMap(pkg =>
    (pkg.vulnerabilities || []).map(v => ({
      package: pkg.package?.name || "unknown",
      version: pkg.package?.version || "unknown",
      id: v.id || "unknown",
      severity: (v.database_specific?.severity || v.severity?.[0]?.type || "unknown").toString()
    }))
  )
);
// Fail closed on every detected vulnerability, including unknown severities.
// Human triage can subsequently document exceptions in a separate reviewed PR.
if (findings.length) {
  for (const finding of findings) process.stderr.write(JSON.stringify(finding) + "\n");
  fail(`${findings.length} vulnerabilities require triage/remediation`);
}
process.stdout.write("OSV report evidence shape validated: no findings reported. Independently confirm snapshot/lockfile hashes and offline scanner invocation.\n");
